  "x50-tw-ripple": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Lab ripple</title>\n  <style>\n    body { margin: 0; min-height: 100vh; display: grid; place-items: center; background: #e8eaee; }\n    .x50-tw-ripple-root { display: inline-flex; align-items: center; justify-content: center; width: 100%; min-height: 72px; }\n.x50-tw-ripple {\n  --x50-tw-ripple: 1;\n  appearance: none;\n  position: relative;\n  isolation: isolate;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  box-sizing: border-box;\n  margin: 0;\n  font-family: system-ui, sans-serif;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n}\n.x50-tw-ripple:focus-visible { outline: 2px solid rgba(255,255,255,.35); outline-offset: 3px; }\n.x50-tw-ripple:disabled { cursor: not-allowed; opacity: 0.42; }\n.x50-tw-ripple *, .x50-tw-ripple *::before, .x50-tw-ripple *::after { box-sizing: border-box; }\n@media (prefers-reduced-motion: reduce) {\n  .x50-tw-ripple, .x50-tw-ripple *, .x50-tw-ripple *::before, .x50-tw-ripple *::after { animation: none !important; transition: none !important; }\n}\n.x50-tw-ripple { padding: 11px 22px; border: 0; border-radius: 999px; background: #27272a; color: #fafafa; font-weight: 600; overflow: hidden; }\n.x50-tw-ripple .wave { position: absolute; border-radius: 50%; background: rgba(255,255,255,.35); transform: scale(0); animation: x50-tw-ripple-rip .6s ease-out; pointer-events: none; }\n@keyframes x50-tw-ripple-rip { to { transform: scale(4); opacity: 0; } }\n  </style>\n</head>\n<body>\n  <div class=\"x50-tw-ripple-root\"><button class=\"x50-tw-ripple\" type=\"button\" data-x50=\"x50-tw-ripple\" aria-label=\"Ripple\">Ripple</button></div>\n  <script>(function(btn){if(!btn)return;btn.addEventListener(\"click\",function(e){if(btn.disabled)return;var r=btn.getBoundingClientRect(),s=Math.max(r.width,r.height)*1.1,w=document.createElement(\"span\");w.className=\"wave\";w.style.width=s+\"px\";w.style.height=s+\"px\";w.style.left=(e.clientX-r.left-s/2)+\"px\";w.style.top=(e.clientY-r.top-s/2)+\"px\";btn.appendChild(w);setTimeout(function(){w.remove();},650);});})(document.querySelector(\".x50-tw-ripple\"));</script>\n</body>\n</html>\n",
